def main():
 names=['smallville-native-mechanism-005','smallville-benchmark-001','smallville-original-benchmark-001','smallville-validation-001','smallville-neutral-validation-audit-002']
 results={n:json.loads((GLOBAL/n/'results.json').read_text()) for n in names}
 for n in names:
  if not json.loads((GLOBAL/n/'langfuse-audit-001.json').read_text())['all_reconciled']:raise ValueError('Missing Langfuse reconciliation')
 cells=[c for r in results.values() for c in r['cells']];ids=[x.split(':response:',1)[1] for c in cells for x in c['native_response_ids']]
 if len(ids)!=len(set(ids)):raise ValueError('Duplicate native response across studies')
 caproot=GLOBAL/'smallville-native-mechanism-003/captures';finals={p.stem for p in caproot.glob('*.json')};pending={p.stem for p in (caproot/'pending').glob('*.json')}
 if pending-finals:raise ValueError('Unfinished capture operation; no final accounting approval')
 observed=[]
 for p in caproot.glob('*.json'):
  c=read_capture(p)
  if c.get('status')!=200 or c.get('state')!='complete':raise ValueError('Unresolved transport outcome')
  observed+=c.get('response_ids',[])
 if len(observed)!=len(set(observed)) or set(ids)!=set(observed):raise ValueError('Unallocated transport response')
 ref=GLOBAL/'lhtb2-source-review-001/unknown-controls-003/reference/complete.json'
 if not ref.exists():raise ValueError('Registered paced reference control still running')
 control=json.loads(ref.read_text())
 local=[]
 local_roots=[GLOBAL/('smallville-native-mechanism-'+v) for v in ('002','003','004','005')]+[GLOBAL/'smallville-native-replay-006']+[GLOBAL/n for n in names[1:]]
 for root in local_roots:
  p=root/'embedding-inferences.jsonl'
  if p.exists():local += [json.loads(x) for x in p.read_text().splitlines()]
 receipt=dict(unique_native_responses=len(ids),model_processes=len(cells),all_responses_allocated=True,native_cli_transport_langfuse_reconciled=True,unfinished_transport_operations=0,measured_study_usage={k:sum(c['usage'][k] for c in cells) for k in ('input_tokens','cached_input_tokens','output_tokens','total_tokens')},measured_study_credit_rate_scenario_lower_bound=sum(c['cost'] for c in cells),local_recorded_embedding_calls=len(local),local_recorded_embedding_seconds=sum(x['seconds'] for x in local),research_parent_and_setup_inference=None,cash_cost=None,quota_saving=None,accounting='All completed study arms, judges and mechanism included once. Parent analysis/setup overhead and incomplete local startup accounting remain additional/unknown; not net first-use savings.',reference_control=control)
 output=HERE.parent/'studies/smallville-final-accounting-001.json'
